declare const tools: { mcp__plan__create_ui_plan(args: { brief?: string; comments?: Array<{ anchor?: string; authorEmail?: string; authorName?: string; createdBy?: "agent" | "human" | "import"; id?: string; kind?: "comment" | "correction" | "question" | "decision" | "annotation"; mentions?: unknown; message: string; parentCommentId?: string; resolutionTarget?: "agent" | "human"; resolvedAt?: unknown; resolvedBy?: unknown; sectionId?: string; status?: "open" | "resolved"; }>; components?: Array<{ description: string; name: string; }>; content?: { blocks?: Array<unknown>; brief?: string; canvas?: { annotations?: unknown; design?: unknown; flow?: unknown; frames?: unknown; mode?: "wireframe" | "design"; notes?: unknown; sections?: unknown; title?: string; viewport?: unknown; }; notionSync?: boolean; prototype?: { brief?: string; initialScreenId?: string; screens: unknown; surface?: "desktop" | "mobile" | "popover" | "panel" | "browser"; title?: string; transitions?: unknown; }; title?: string; version: number; }; currentFocus?: string; goal?: string; implementationNotes?: string; markdown?: string; repoPath?: string; sections?: Array<{ body?: string; createdBy?: "agent" | "human" | "import"; html?: string; id?: string; order?: number; title: string; type?: "summary" | "diagram" | "wireframe" | "mockup" | "prototype" | "steps" | "implementation" | "decisions" | "questions" | "risks" | "notes" | "custom"; }>; source?: "claude-code" | "codex" | "cursor" | "pi" | "manual" | "imported"; states?: Array<{ description: string; name: string; }>; status?: "draft" | "review" | "approved" | "in_progress" | "complete" | "archived"; title?: string; }): Promise<CallToolResult>; };
```"}

